const fs = require('fs');

const path = '.env.test';
const content = fs.readFileSync(path, 'utf8');

function preview(val) {
  if (!val) return '';
  const v = String(val);
  if (v.length <= 8) return `${v.slice(0, 1)}…${v.slice(-1)}`;
  return `${v.slice(0, 4)}…${v.slice(-4)}`;
}

for (const line of content.split(/\r?\n/)) {
